import torch
import torch.nn as nn
from torch.autograd import Function
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <float.h>

template <int BLOCK_SIZE>
__global__ void softmax_fp16_kernel(const __half* __restrict__ input,
                                    __half* __restrict__ output,
                                    const int dim) {
    // one block = one row (batch element)
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const __half* in_row  = input  + (size_t)row * dim;
    __half*       out_row = output + (size_t)row * dim;

    // ---------- max reduction ----------
    float max_val = -FLT_MAX;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        float v = __half2float(in_row[i]);
        if (v > max_val) max_val = v;
    }
    __shared__ float smax[BLOCK_SIZE];
    smax[tid] = max_val;
    __syncthreads();

    // parallel reduction for max
    #pragma unroll
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            float other = smax[tid + stride];
            if (other > smax[tid]) smax[tid] = other;
        }
        __syncthreads();
    }
    max_val = smax[0];
    __syncthreads();

    // ---------- sum of exp reduction ----------
    float sum_val = 0.0f;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        float v = __half2float(in_row[i]);
        sum_val += expf(v - max_val);
    }
    __shared__ float ssum[BLOCK_SIZE];
    ssum[tid] = sum_val;
    __syncthreads();

    // parallel reduction for sum
    #pragma unroll
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            ssum[tid] += ssum[tid + stride];
        }
        __syncthreads();
    }
    sum_val = ssum[0];
    __syncthreads();

    // ---------- write output ----------
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        float v = __half2float(in_row[i]);
        float prob = expf(v - max_val) / sum_val;
        out_row[i] = __float2half(prob);
    }
}

// Wrapper for launch
void launch_softmax_fp16(const at::Tensor& input, at::Tensor& output) {
    const int batch = input.size(0);
    const int dim   = input.size(1);
    const int BLOCK_SIZE = 256;               // 256 threads per block
    const dim3 grid(batch);
    const dim3 block(BLOCK_SIZE);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "softmax_fp16_kernel", ([&] {
        softmax_fp16_kernel<BLOCK_SIZE><<<grid, block>>>(
            reinterpret_cast<const __half*>(input.data_ptr<scalar_t>()),
            reinterpret_cast<__half*>(output.data_ptr<scalar_t>()),
            dim);
    }));
    cudaGetLastError(); // for debugging launch failures
}
'''

# Compile the CUDA kernel
softmax_module = load_inline(
    name='softmax_fp16_module',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['launch_softmax_fp16'],
    verbose=False,
)

class SoftmaxFP16Function(Function):
    @staticmethod
    def forward(ctx, x):
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        x = x.contiguous()
        out = torch.empty_like(x, dtype=torch.float16, device='cuda')
        softmax_module.launch_softmax_fp16(x, out)
        ctx.save_for_backward(out)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        (y,) = ctx.saved_tensors          # y = softmax(x)
        # grad_input = y * (grad_output - sum(grad_output * y))
        grad_output = grad_output.to(torch.float16)
        sum_gy_y = (grad_output * y).sum(dim=1, keepdim=True)
        grad_input = y * (grad_output - sum_gy_y)
        return grad_input

class ModelNew(nn.Module):
    """
    Model that performs Softmax activation using a custom FP16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return SoftmaxFP16Function.apply(x)

# Helper functions matching the reference API
def get_inputs():
    batch_size = 4096
    dim = 393216
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return []  # No special initialization inputs needed
